mapper.select:
WITH DATA_UPLOAD AS(
SELECT #{item.lotId,jdbcType=VARCHAR} LOT_ID ,#{item.requestDate,jdbcType=VARCHAR} REQUEST_DAY ,#{item.targetOPE,jdbcType=VARCHAR} TARGET_OPE ,#{item.purpose,jdbcType=VARCHAR} PURPOSE ,#{updateUser} UPDATE_USER FROM DUAL
),BASE_LOT_DETAIL AS( SELECT A.LOT_ID,A.TARGET_OPE,A.REQUEST_DAY,A.PURPOSE,A.UPDATE_USER,B.MAINPD_ID,B.LOT_PROC_STATE,B.WAFER_QTY,B.PRODSPEC_ID,B.STB_TIME,B.OPE_NO,B.LAST_CLAIM_TIME,B.CASSETE_ID FROM DATA_UPLOAD A LEFT JOIN A3MFGYW1.V_LOT_SUMMARY B ON A.LOT_ID = B.LOT_ID ) SELECT QUESTION FROM( SELECT A.LOT_ID,A.REQUEST_DAY ,A.TARGET_OPE,A.PURPOSE,A.UPDATE_USER,SYSDATE UPDATE_TIME ,CASE WHEN C.LOT_ID IS NOT NULL THEN A.LOT_ID ||' 已上传' END QUESTION FROM BASE_LOT_DETAIL A LEFT JOIN ( SELECT LOT_ID FROM A1MFG.PULLIN_LOT_UPLOAD@TO_A1PDW WHERE FUNCTION_NAME = #{source ,jdbcType=VARCHAR} ) C ON A.LOT_ID = C.LOT_ID )WHERE QUESTION IS NOT NULL

mapper.insert:
MERGE INTO A1MFG.PULLIN_LOT_UPLOAD A USING( WITH DATA_UPLOAD AS(
SELECT #{item.lotId,jdbcType=VARCHAR} LOT_ID ,#{item.requestDate,jdbcType=VARCHAR} REQUEST_DAY ,#{item.targetOPE,jdbcType=VARCHAR} TARGET_OPE ,#{item.purpose,jdbcType=VARCHAR} PURPOSE ,#{updateUser} UPDATE_USER,#{source}FUNCTION_NAME FROM DUAL
),BASE_LOT_DETAIL AS( SELECT A.FUNCTION_NAME,A.LOT_ID,A.TARGET_OPE,A.REQUEST_DAY,A.PURPOSE,A.UPDATE_USER,B.MAINPD_ID,B.LOT_PROC_STATE,B.WAFER_QTY,B.PRODSPEC_ID,B.STB_TIME,B.OPE_NO,B.LAST_CLAIM_TIME,B.CASSETE_ID FROM DATA_UPLOAD A LEFT JOIN A3MFGYW1.V_LOT_SUMMARY@TO_A3MFG B ON A.LOT_ID = B.LOT_ID WHERE B.LOT_INV_STATE = 'OnFloor' ),DYB_LOT_LIST AS( SELECT LOT_ID,MAINPD_ID,LOT_PROC_STATE,WAFER_QTY,PRODSPEC_ID,STB_TIME,OPE_NO,LAST_CLAIM_TIME,CASSETE_ID FROM BASE_LOT_DETAIL WHERE MAINPD_ID LIKE 'YY%' OR MAINPD_ID LIKE 'YX%' OR MAINPD_ID LIKE 'B%' OR MAINPD_ID LIKE 'DYB%' ),DYB_LOT_LAST_OPENO AS( SELECT LOT_ID,MAINPD_ID,OPE_NO,LOT_PROC_STATE,WAFER_QTY,PRODSPEC_ID,STB_TIME,LAST_MAIN_OPENO,LAST_CLAIM_TIME,CASSETE_ID,CLAIM_TIME FROM( SELECT LOT_ID,MAINPD_ID,OPE_NO,LOT_PROC_STATE,WAFER_QTY,PRODSPEC_ID,STB_TIME,LAST_MAIN_OPENO,LAST_CLAIM_TIME,CASSETE_ID,CLAIM_TIME ,ROW_NUMBER()OVER(PARTITION BY LOT_ID ORDER BY CLAIM_TIME DESC)RN FROM( SELECT A.LOT_ID,A.MAINPD_ID,A.OPE_NO,A.LOT_PROC_STATE,A.WAFER_QTY,A.PRODSPEC_ID,A.STB_TIME,NVL(B.OPE_NO,A.OPE_NO)LAST_MAIN_OPENO ,A.LAST_CLAIM_TIME,A.CASSETE_ID,B.CLAIM_TIME FROM DYB_LOT_LIST A LEFT JOIN ODS.FHOPEHS B ON A.LOT_ID = B.LOT_ID WHERE (B.OPE_CATEGORY = 'Branch' OR B.OPE_CATEGORY = 'Rework') AND B.MAINPD_ID NOT LIKE 'YY%' AND B.MAINPD_ID NOT LIKE 'YX%' AND B.MAINPD_ID NOT LIKE 'DYB%' AND B.MAINPD_ID NOT LIKE 'B%' UNION ALL SELECT A.LOT_ID,A.MAINPD_ID,A.OPE_NO,A.LOT_PROC_STATE,A.WAFER_QTY,A.PRODSPEC_ID,A.STB_TIME,NVL(B.OPE_NO,A.OPE_NO)LAST_MAIN_OPENO ,A.LAST_CLAIM_TIME,A.CASSETE_ID,B.CLAIM_TIME FROM DYB_LOT_LIST A LEFT JOIN PWEB.FHOPEHS_A3 B ON A.LOT_ID = B.LOT_ID WHERE (B.OPE_CATEGORY = 'Branch' OR B.OPE_CATEGORY = 'Rework') AND B.MAINPD_ID NOT LIKE 'YY%' AND B.MAINPD_ID NOT LIKE 'YX%' AND B.MAINPD_ID NOT LIKE 'DYB%' AND B.MAINPD_ID NOT LIKE 'B%' ))WHERE RN=1 ) ,BASE_LOT_INFO AS( SELECT LOT_ID,MAINPD_ID,LOT_PROC_STATE,WAFER_QTY,PRODSPEC_ID,STB_TIME,OPE_NO,LAST_CLAIM_TIME,CASSETE_ID,OPE_NO LAST_MAIN_OPENO FROM BASE_LOT_DETAIL A WHERE MAINPD_ID NOT LIKE 'YY%' AND MAINPD_ID NOT LIKE 'YX%' AND MAINPD_ID NOT LIKE 'B%' AND MAINPD_ID NOT LIKE 'DYB%' UNION ALL SELECT LOT_ID,MAINPD_ID,LOT_PROC_STATE,WAFER_QTY,PRODSPEC_ID,STB_TIME,OPE_NO,LAST_CLAIM_TIME,CASSETE_ID,LAST_MAIN_OPENO FROM DYB_LOT_LAST_OPENO B ),BASE_INFO AS( SELECT A.*,B.PRODG1,C.MFG_TECH TECH ,CASE WHEN A.MAINPD_ID LIKE 'YY%' OR A.MAINPD_ID LIKE 'YX%' OR A.MAINPD_ID LIKE 'B%' OR A.MAINPD_ID LIKE 'DYB%' THEN B.FLOW_ID ELSE A.MAINPD_ID END FLOW_ID ,D.REQUEST_DAY ,D.TARGET_OPE ,D.PURPOSE FROM BASE_LOT_INFO A LEFT JOIN ODS.WP_PRODUCT B ON A.PRODSPEC_ID =B.PRODSPEC_ID LEFT JOIN A1MFG.PRODUCT_TECH_INFO C ON B.PRODG1 = C.PRODG1 LEFT JOIN A1MFG.PULLIN_LOT_UPLOAD D ON A.LOT_ID = D.LOT_ID ),FLOW_BASE_INFO AS( SELECT PRODG1,ACT_PRODSPEC_ID,PRODSPEC_ID, OPER_NO,ROW_NUMBER()OVER(PARTITION BY ACT_PRODSPEC_ID ORDER BY LENGTH(PRODSPEC_ID),OPER_SEQ)OPER_SEQ FROM( SELECT A.PRODG1,A.PRODSPEC_ID ACT_PRODSPEC_ID,A.PRODSPEC_ID,B.OPER_NO ,B.OPER_SEQ FROM( SELECT DISTINCT FLOW_ID,PRODSPEC_ID,PRODG1 FROM BASE_INFO WHERE (TECH = 'C55STACK'AND PRODG1 NOT LIKE 'C55____M' AND PRODG1 NOT LIKE 'C55____A') OR TECH <>'C55STACK' )A LEFT JOIN ODS.WP_FLOW B ON A.FLOW_ID = B.FLOW_KEY UNION ALL SELECT A.PRODG1,A.ACT_PRODSPEC_ID,A.PRODSPEC_ID,B.OPER_NO ,B.OPER_SEQ FROM( SELECT D.PRODG1,C.ACT_PRODSPEC_ID ,C.PRODSPEC_ID ,D.FLOW_ID FROM( SELECT DISTINCT PRODSPEC_ID ACT_PRODSPEC_ID, PRODSPEC_ID||'_'PRODSPEC_ID FROM BASE_INFO WHERE (TECH = 'C55STACK' AND PRODG1 NOT LIKE 'C55____M' AND PRODG1 NOT LIKE 'C55____A') OR TECH <>'C55STACK' )C LEFT JOIN ODS.WP_PRODUCT D ON C.PRODSPEC_ID = D.PRODSPEC_ID )A LEFT JOIN ODS.WP_FLOW B ON A.FLOW_ID = B.FLOW_KEY ) ),STACK_FLOW_INFO_PIXEL AS( SELECT PRODG1,ACT_PRODSPEC_ID,PRODSPEC_ID,OPER_NO,ROW_NUMBER()OVER(PARTITION BY ACT_PRODSPEC_ID ORDER BY FLAG,OPER_SEQ)OPER_SEQ FROM( SELECT A.PRODG1,A.PRODSPEC_ID ACT_PRODSPEC_ID,A.PRODSPEC_ID,B.OPER_NO ,B.OPER_SEQ,1 FLAG FROM( SELECT DISTINCT FLOW_ID,PRODSPEC_ID,PRODG1 FROM BASE_INFO WHERE (TECH = 'C55STACK' AND PRODG1 LIKE 'C55____M') )A LEFT JOIN ODS.WP_FLOW B ON A.FLOW_ID = B.FLOW_KEY UNION ALL SELECT G.PRODG1,G.ACT_PRODSPEC_ID ,G.PRODSPEC_ID,H.OPER_NO,H.OPER_SEQ,2 FLAG FROM( SELECT D.PRODG1,D.ACT_PRODSPEC_ID,D.PRODSPEC_ID,E.FLOW_ID FROM( SELECT A.PRODG1,A.PRODSPEC_ID ACT_PRODSPEC_ID,B.OUTPUT_PRODG,C.CHIPBODY||'.'||SUBSTR(A.PRODSPEC_ID,INSTR(A.PRODSPEC_ID,'.')+1,4) PRODSPEC_ID FROM( SELECT DISTINCT PRODSPEC_ID,PRODG1 FROM BASE_INFO WHERE (TECH = 'C55STACK' AND PRODG1 LIKE 'C55____M') )A LEFT JOIN A1MFG.STACK_LOGIC_RELATED B ON A.PRODG1 = B.PIXEL_PRODG LEFT JOIN PWEB.PRODUCT_INFO C ON B.OUTPUT_PRODG = C.PRODG1 )D LEFT JOIN ODS.WP_PRODUCT E ON D.PRODSPEC_ID = E.PRODSPEC_ID )G LEFT JOIN ODS.WP_FLOW H ON G.FLOW_ID = H.FLOW_KEY UNION ALL SELECT G.PRODG1,G.ACT_PRODSPEC_ID ,G.PRODSPEC_ID,H.OPER_NO,H.OPER_SEQ,3 FLAG FROM( SELECT D.PRODG1,D.ACT_PRODSPEC_ID,D.PRODSPEC_ID,E.FLOW_ID FROM( SELECT A.PRODG1,A.PRODSPEC_ID ACT_PRODSPEC_ID,B.OUTPUT_PRODG,C.CHIPBODY||'.'||SUBSTR(A.PRODSPEC_ID,INSTR(A.PRODSPEC_ID,'.')+1,4)||'_' PRODSPEC_ID FROM( SELECT DISTINCT PRODSPEC_ID,PRODG1 FROM BASE_INFO WHERE (TECH = 'C55STACK' AND PRODG1 LIKE 'C55____M') )A LEFT JOIN A1MFG.STACK_LOGIC_RELATED B ON A.PRODG1 = B.PIXEL_PRODG LEFT JOIN PWEB.PRODUCT_INFO C ON B.OUTPUT_PRODG = C.PRODG1 )D LEFT JOIN ODS.WP_PRODUCT E ON D.PRODSPEC_ID = E.PRODSPEC_ID )G LEFT JOIN ODS.WP_FLOW H ON G.FLOW_ID = H.FLOW_KEY ) ),STACK_FLOW_INFO_OUTPUT AS( SELECT PRODG1,ACT_PRODSPEC_ID,PRODSPEC_ID,OPER_NO,ROW_NUMBER()OVER(PARTITION BY ACT_PRODSPEC_ID ORDER BY FLAG,OPER_SEQ)OPER_SEQ FROM( SELECT A.PRODG1,A.PRODSPEC_ID ACT_PRODSPEC_ID,A.PRODSPEC_ID,B.OPER_NO ,B.OPER_SEQ,2 FLAG FROM( SELECT DISTINCT FLOW_ID,PRODSPEC_ID,PRODG1 FROM BASE_INFO WHERE (TECH = 'C55STACK' AND PRODG1 LIKE 'C55____A') )A LEFT JOIN ODS.WP_FLOW B ON A.FLOW_ID = B.FLOW_KEY UNION ALL SELECT G.PRODG1,G.ACT_PRODSPEC_ID ,G.PRODSPEC_ID,H.OPER_NO,H.OPER_SEQ,1 FLAG FROM( SELECT D.PRODG1,D.ACT_PRODSPEC_ID,D.PRODSPEC_ID,E.FLOW_ID FROM( SELECT A.PRODG1,A.PRODSPEC_ID ACT_PRODSPEC_ID,B.OUTPUT_PRODG,C.CHIPBODY||'.'||SUBSTR(A.PRODSPEC_ID,INSTR(A.PRODSPEC_ID,'.')+1,4) PRODSPEC_ID FROM( SELECT DISTINCT PRODSPEC_ID,PRODG1 FROM BASE_INFO WHERE (TECH = 'C55STACK' AND PRODG1 LIKE 'C55____A') )A LEFT JOIN A1MFG.STACK_LOGIC_RELATED B ON A.PRODG1 = B.OUTPUT_PRODG LEFT JOIN PWEB.PRODUCT_INFO C ON B.PIXEL_PRODG = C.PRODG1 )D LEFT JOIN ODS.WP_PRODUCT E ON D.PRODSPEC_ID = E.PRODSPEC_ID )G LEFT JOIN ODS.WP_FLOW H ON G.FLOW_ID = H.FLOW_KEY UNION ALL SELECT G.PRODG1,G.ACT_PRODSPEC_ID ,G.PRODSPEC_ID,H.OPER_NO,H.OPER_SEQ,3 FLAG FROM( SELECT D.PRODG1,D.ACT_PRODSPEC_ID,D.PRODSPEC_ID,E.FLOW_ID FROM( SELECT A.PRODG1,A.PRODSPEC_ID ACT_PRODSPEC_ID,A.PRODSPEC_ID||'_' PRODSPEC_ID FROM( SELECT DISTINCT PRODSPEC_ID,PRODG1 FROM BASE_INFO WHERE (TECH = 'C55STACK' AND PRODG1 LIKE 'C55____A') )A )D LEFT JOIN ODS.WP_PRODUCT E ON D.PRODSPEC_ID = E.PRODSPEC_ID )G LEFT JOIN ODS.WP_FLOW H ON G.FLOW_ID = H.FLOW_KEY )) ,FLOW_INFO_ALL AS( SELECT PRODG1,ACT_PRODSPEC_ID,PRODSPEC_ID,OPER_NO,OPER_SEQ,CT,TM,TP,TQ ,LAYER_STEP_SEQ/LAYER_STEP_COUNT +SUM(CASE WHEN LAYER_STEP_SEQ=1 THEN 1 ELSE 0 END)OVER(PARTITION BY ACT_PRODSPEC_ID ORDER BY OPER_SEQ)-1 REMAIN_LAYER FROM( SELECT PRODG1,ACT_PRODSPEC_ID,PRODSPEC_ID,OPER_NO,OPER_SEQ,CT,TM,TP,TQ ,COUNT(1)OVER(PARTITION BY ACT_PRODSPEC_ID,SUBSTR(OPER_NO,1,2))LAYER_STEP_COUNT ,ROW_NUMBER()OVER(PARTITION BY ACT_PRODSPEC_ID,SUBSTR(OPER_NO,1,2) ORDER BY OPER_SEQ)LAYER_STEP_SEQ FROM( SELECT PRODG1,ACT_PRODSPEC_ID,PRODSPEC_ID,OPER_NO,OPER_SEQ,CT,TM,TP ,CASE WHEN TQ IS NOT NULL THEN TQ WHEN CT - TM - TP < 0 THEN 0 ELSE CT - TM - TP END TQ FROM( SELECT A.*,B.TQ ,CASE WHEN B.CT IS NOT NULL THEN B.CT WHEN NVL(E.SAMPLING_RATE,1) = 0 THEN 0 ELSE D.INLINE_CT END CT ,CASE WHEN B.TM IS NOT NULL THEN B.TM WHEN NVL(E.SAMPLING_RATE,1) = 0 THEN 0 WHEN SUBSTR(A.OPER_NO,5,1) = 'Q' OR A.OPER_NO LIKE '%SXW%' OR A.OPER_NO LIKE '%SXN%' THEN D.TC+0.1 ELSE D.TC+0.2 END TM ,CASE WHEN B.TP IS NOT NULL THEN B.TP WHEN NVL(E.SAMPLING_RATE,1) = 0 THEN 0 ELSE 0.05 END TP FROM( SELECT PRODG1,ACT_PRODSPEC_ID,PRODSPEC_ID,OPER_NO,OPER_SEQ FROM FLOW_BASE_INFO UNION ALL SELECT PRODG1,ACT_PRODSPEC_ID,PRODSPEC_ID,OPER_NO,OPER_SEQ FROM STACK_FLOW_INFO_PIXEL UNION ALL SELECT PRODG1,ACT_PRODSPEC_ID,PRODSPEC_ID,OPER_NO,OPER_SEQ FROM STACK_FLOW_INFO_OUTPUT )A LEFT JOIN A1MFG.PRODUCT_FLOW_INFO B ON A.PRODG1 = B.PRODG1 AND A.OPER_NO = B.OPER_NO LEFT JOIN PWEB.OPE_NO_INLINE_FLOW_PSTD D ON A.PRODSPEC_ID = D.PRODSPEC_ID AND A.OPER_NO = D.OPE_NO LEFT JOIN PWEB.SAMPLING_RATE E ON A.PRODSPEC_ID = E.PRODSPEC_ID AND A.OPER_NO = E.OPE_NO )C ))) SELECT A.FUNCTION_NAME,A.LOT_ID,A.REQUEST_DAY ,A.TARGET_OPE,A.PURPOSE,A.UPDATE_USER,SYSDATE UPDATE_TIME,B.OPER_SEQ,B.REMAIN_LAYER LAYER_COUNT FROM BASE_LOT_DETAIL A LEFT JOIN FLOW_INFO_ALL B ON A.PRODSPEC_ID = B.ACT_PRODSPEC_ID AND A.TARGET_OPE = B.OPER_NO )B ON (A.LOT_ID = B.LOT_ID AND A.FUNCTION_NAME = B.FUNCTION_NAME) WHEN NOT MATCHED THEN INSERT (LOT_ID,REQUEST_DAY,TARGET_OPE,PURPOSE,UPDATE_USER,UPDATE_TIME,OPER_SEQ,LAYER_COUNT,FUNCTION_NAME) VALUES (B.LOT_ID,B.REQUEST_DAY ,B.TARGET_OPE,B.PURPOSE,B.UPDATE_USER,SYSDATE,B.OPER_SEQ,B.LAYER_COUNT,B.FUNCTION_NAME)

INSERT INTO A1MFG.PULLIN_LOT_FLOW_CT(FUNCTION_NAME,LOT_ID,PRODSPEC_ID,LAST_MAIN_OPENO,CUR_SEQ,OPER_NO,OPER_SEQ,TM,STD_CT,CT_FORECAST,FLOW_TF,LAYER_COUNT,UPDATE_TIME) WITH DATA_UPLOAD_DATA AS( SELECT LOT_ID,REQUEST_DAY,TARGET_OPE,PURPOSE,UPDATE_USER,FUNCTION_NAME FROM( SELECT LOT_ID,REQUEST_DAY,TARGET_OPE,PURPOSE,UPDATE_USER,FUNCTION_NAME, ROW_NUMBER()OVER(PARTITION BY LOT_ID ORDER BY REQUEST_DAY )RN FROM(
SELECT #{item.lotId,jdbcType=VARCHAR} LOT_ID ,#{item.requestDate,jdbcType=VARCHAR} REQUEST_DAY ,#{item.targetOPE,jdbcType=VARCHAR} TARGET_OPE ,#{item.purpose,jdbcType=VARCHAR} PURPOSE ,#{updateUser} UPDATE_USER,#{source}FUNCTION_NAME FROM DUAL
))WHERE RN=1 ),DATA_UPLOAD AS( SELECT A.* FROM DATA_UPLOAD_DATA A LEFT JOIN A1MFG.PULLIN_LOT_UPLOAD B ON A.LOT_ID = B.LOT_ID ) ,BASE_LOT_DETAIL AS( SELECT A.FUNCTION_NAME,A.LOT_ID,A.TARGET_OPE,A.REQUEST_DAY,A.PURPOSE,A.UPDATE_USER ,B.MAINPD_ID,B.LOT_PROC_STATE,B.WAFER_QTY,B.PRODSPEC_ID,B.STB_TIME,B.OPE_NO,B.LAST_CLAIM_TIME,B.CASSETE_ID ,B.FAB,B.LOCATION FROM DATA_UPLOAD A LEFT JOIN A3MFGYW1.V_LOT_SUMMARY@TO_A3MFG B ON A.LOT_ID = B.LOT_ID ) ,DYB_LOT_LIST AS( SELECT FUNCTION_NAME, LOT_ID,MAINPD_ID,LOT_PROC_STATE,WAFER_QTY,PRODSPEC_ID,STB_TIME,OPE_NO,LAST_CLAIM_TIME,CASSETE_ID ,FAB,LOCATION FROM BASE_LOT_DETAIL WHERE MAINPD_ID LIKE 'YY%' OR MAINPD_ID LIKE 'YX%' OR MAINPD_ID LIKE 'B%' OR MAINPD_ID LIKE 'DYB%' ) ,DYB_LOT_LAST_OPENO AS( SELECT FUNCTION_NAME,FAB,LOCATION, LOT_ID,MAINPD_ID,OPE_NO,LOT_PROC_STATE,WAFER_QTY,PRODSPEC_ID,STB_TIME,LAST_MAIN_OPENO,LAST_CLAIM_TIME,CASSETE_ID,CLAIM_TIME FROM( SELECT FUNCTION_NAME,FAB,LOCATION, LOT_ID,MAINPD_ID,OPE_NO,LOT_PROC_STATE,WAFER_QTY,PRODSPEC_ID,STB_TIME,LAST_MAIN_OPENO,LAST_CLAIM_TIME,CASSETE_ID,CLAIM_TIME ,ROW_NUMBER()OVER(PARTITION BY LOT_ID,FUNCTION_NAME ORDER BY CLAIM_TIME DESC)RN FROM( SELECT A.FUNCTION_NAME ,A .FAB,A.LOCATION, A.LOT_ID,A.MAINPD_ID,A.OPE_NO,A.LOT_PROC_STATE,A.WAFER_QTY,A.PRODSPEC_ID,A.STB_TIME,NVL(B.OPE_NO,A.OPE_NO)LAST_MAIN_OPENO ,A.LAST_CLAIM_TIME,A.CASSETE_ID,B.CLAIM_TIME FROM DYB_LOT_LIST A LEFT JOIN ODS.FHOPEHS B ON A.LOT_ID = B.LOT_ID WHERE (B.OPE_CATEGORY = 'Branch' OR B.OPE_CATEGORY = 'Rework') AND B.MAINPD_ID NOT LIKE 'YY%' AND B.MAINPD_ID NOT LIKE 'YX%' AND B.MAINPD_ID NOT LIKE 'DYB%' AND B.MAINPD_ID NOT LIKE 'B%' UNION ALL SELECT A.FUNCTION_NAME ,A .FAB,A.LOCATION, A.LOT_ID,A.MAINPD_ID,A.OPE_NO,A.LOT_PROC_STATE,A.WAFER_QTY,A.PRODSPEC_ID,A.STB_TIME,NVL(B.OPE_NO,A.OPE_NO)LAST_MAIN_OPENO ,A.LAST_CLAIM_TIME,A.CASSETE_ID,B.CLAIM_TIME FROM DYB_LOT_LIST A LEFT JOIN PWEB.FHOPEHS_A3 B ON A.LOT_ID = B.LOT_ID WHERE (B.OPE_CATEGORY = 'Branch' OR B.OPE_CATEGORY = 'Rework') AND B.MAINPD_ID NOT LIKE 'YY%' AND B.MAINPD_ID NOT LIKE 'YX%' AND B.MAINPD_ID NOT LIKE 'DYB%' AND B.MAINPD_ID NOT LIKE 'B%' ))WHERE RN=1 ) ,OPE_NO_INFO_0730 AS( SELECT LOT_ID,OPE_NO,COMPLETE_TIME FROM( SELECT LOT_ID,COMPLETE_TIME,PREV_OP_COMP_TIME,OPE_NO ,ROW_NUMBER()OVER(PARTITION BY LOT_ID ORDER BY PREV_OP_COMP_TIME DESC,START_TIME DESC,COMPLETE_TIME DESC)RN FROM A3MFGYW1.V_MOVE_SUMMARY@TO_A3MFG A WHERE MOVE_FLAG =1 AND SHIFT_DATE = TO_CHAR(SYSDATE-7.5/24-1,'YYYYMMDD') AND MAINPD_ID NOT LIKE 'YY%' AND MAINPD_ID NOT LIKE 'YX%' AND MAINPD_ID NOT LIKE 'DYB%' AND MAINPD_ID NOT LIKE 'B%' AND EXISTS( SELECT 1 FROM( SELECT LOT_ID FROM BASE_LOT_DETAIL )B WHERE A.LOT_ID = B.LOT_ID ))WHERE RN =1 ) ,BASE_LOT_INFO AS( SELECT FAB,LOCATION,FUNCTION_NAME,LOT_ID,MAINPD_ID,LOT_PROC_STATE,WAFER_QTY,PRODSPEC_ID,STB_TIME,OPE_NO,LAST_CLAIM_TIME,CASSETE_ID,LAST_MAIN_OPENO FROM( SELECT FAB,LOCATION,FUNCTION_NAME, A.LOT_ID,A.MAINPD_ID,A.LOT_PROC_STATE,A.WAFER_QTY,A.PRODSPEC_ID,A.STB_TIME,A.OPE_NO,A.LAST_CLAIM_TIME,A.CASSETE_ID ,NVL(B.OPE_NO,A.LAST_MAIN_OPENO)LAST_MAIN_OPENO,ROW_NUMBER()OVER(PARTITION BY A.LOT_ID,A.FUNCTION_NAME ORDER BY A.LAST_CLAIM_TIME DESC)RN FROM( SELECT A.FAB,A.LOCATION,A.FUNCTION_NAME,LOT_ID,MAINPD_ID,LOT_PROC_STATE,WAFER_QTY,PRODSPEC_ID,STB_TIME,OPE_NO,LAST_CLAIM_TIME,CASSETE_ID,OPE_NO LAST_MAIN_OPENO FROM BASE_LOT_DETAIL A WHERE MAINPD_ID NOT LIKE 'YY%' AND MAINPD_ID NOT LIKE 'YX%' AND MAINPD_ID NOT LIKE 'B%' AND MAINPD_ID NOT LIKE 'DYB%' UNION ALL SELECT B.FAB,B.LOCATION,B.FUNCTION_NAME,LOT_ID,MAINPD_ID,LOT_PROC_STATE,WAFER_QTY,PRODSPEC_ID,STB_TIME,OPE_NO,LAST_CLAIM_TIME,CASSETE_ID,LAST_MAIN_OPENO FROM DYB_LOT_LAST_OPENO B )A LEFT JOIN OPE_NO_INFO_0730 B ON A.LOT_ID = B.LOT_ID )WHERE RN=1 ) ,BASE_INFO AS( SELECT A.*,B.PRODG1,C.MFG_TECH TECH ,CASE WHEN A.MAINPD_ID LIKE 'YY%' OR A.MAINPD_ID LIKE 'YX%' OR A.MAINPD_ID LIKE 'B%' OR A.MAINPD_ID LIKE 'DYB%' THEN B.FLOW_ID ELSE A.MAINPD_ID END FLOW_ID ,D.REQUEST_DAY ,D.TARGET_OPE ,D.PURPOSE FROM BASE_LOT_INFO A LEFT JOIN ( SELECT 'N1A1'FAB, PRODSPEC_ID,PRODG1,FLOW_ID FROM ODS.WP_PRODUCT UNION ALL SELECT 'N1A3'FAB, PRODSPEC_ID,PRODG1,FLOW_ID FROM PWEB.WP_PRODUCT_A3 )B ON A.PRODSPEC_ID =B.PRODSPEC_ID AND A.FAB = B.FAB LEFT JOIN A1MFG.PRODUCT_TECH_INFO C ON B.PRODG1 = C.PRODG1 LEFT JOIN A1MFG.PULLIN_LOT_UPLOAD D ON A.LOT_ID = D.LOT_ID AND A.FUNCTION_NAME = D.FUNCTION_NAME ) ,FLOW_BASE_INFO AS( SELECT FAB, PRODG1,ACT_PRODSPEC_ID,PRODSPEC_ID, OPER_NO,ROW_NUMBER()OVER(PARTITION BY ACT_PRODSPEC_ID,FAB ORDER BY LENGTH(PRODSPEC_ID),OPER_SEQ)OPER_SEQ FROM( SELECT A.FAB,A.PRODG1,A. ACT_PRODSPEC_ID,A.PRODSPEC_ID,B.OPER_NO ,B.OPER_SEQ FROM( SELECT E.FLOW_ID,D.PRODSPEC_ID,D.ACT_PRODSPEC_ID,D.PRODG1,D.FAB FROM( SELECT DISTINCT FLOW_ID,PRODSPEC_ID ACT_PRODSPEC_ID,PRODG1,FAB ,CASE WHEN INSTR(PRODSPEC_ID,'_')>0 THEN REPLACE(PRODSPEC_ID,'_') ELSE PRODSPEC_ID END PRODSPEC_ID FROM BASE_INFO WHERE (TECH = 'C55STACK' AND PRODG1 NOT LIKE 'C55____M' AND PRODG1 NOT LIKE 'C55____A') OR TECH <>'C55STACK' )D LEFT JOIN ( SELECT 'N1A1'FAB, PRODSPEC_ID,PRODG1,FLOW_ID FROM ODS.WP_PRODUCT UNION ALL SELECT 'N1A3'FAB, PRODSPEC_ID,PRODG1,FLOW_ID FROM PWEB.WP_PRODUCT_A3 ) E ON D.PRODSPEC_ID = E.PRODSPEC_ID AND D.FAB = E.FAB )A LEFT JOIN ( SELECT 'N1A1'FAB ,FLOW_KEY,OPER_NO,OPER_SEQ FROM ODS.WP_FLOW UNION ALL SELECT 'N1A3'FAB ,FLOW_KEY,OPER_NO,OPER_SEQ FROM PWEB.WP_FLOW_A3 ) B ON A.FLOW_ID = B.FLOW_KEY AND A.FAB = B.FAB UNION ALL SELECT A.FAB,A.PRODG1,A.ACT_PRODSPEC_ID,A.PRODSPEC_ID,B.OPER_NO ,B.OPER_SEQ FROM( SELECT D.PRODG1,C.ACT_PRODSPEC_ID ,C.PRODSPEC_ID ,D.FLOW_ID,D.FAB FROM( SELECT D.PRODG1,D.ACT_PRODSPEC_ID,D.PRODSPEC_ID,E.FLOW_ID,D.FAB FROM( SELECT A.PRODG1,A.ACT_PRODSPEC_ID,A.PRODSPEC_ID||'_' PRODSPEC_ID,A.FAB FROM( SELECT DISTINCT PRODSPEC_ID ACT_PRODSPEC_ID ,CASE WHEN INSTR(PRODSPEC_ID,'_')>0 THEN REPLACE(PRODSPEC_ID,'_') ELSE PRODSPEC_ID END PRODSPEC_ID ,PRODG1,FAB FROM BASE_INFO WHERE (TECH = 'C55STACK' AND PRODG1 NOT LIKE 'C55____M' AND PRODG1 NOT LIKE 'C55____A') OR TECH <>'C55STACK' )A )D LEFT JOIN ( SELECT 'N1A1'FAB, PRODSPEC_ID,PRODG1,FLOW_ID FROM ODS.WP_PRODUCT UNION ALL SELECT 'N1A3'FAB, PRODSPEC_ID,PRODG1,FLOW_ID FROM PWEB.WP_PRODUCT_A3 ) E ON D.PRODSPEC_ID = E.PRODSPEC_ID AND D.FAB = E.FAB )C LEFT JOIN ( SELECT 'N1A1'FAB, PRODSPEC_ID,PRODG1,FLOW_ID FROM ODS.WP_PRODUCT UNION ALL SELECT 'N1A3'FAB, PRODSPEC_ID,PRODG1,FLOW_ID FROM PWEB.WP_PRODUCT_A3 ) D ON C.PRODSPEC_ID = D.PRODSPEC_ID AND C.FAB = D.FAB )A LEFT JOIN ( SELECT 'N1A1'FAB ,FLOW_KEY,OPER_NO,OPER_SEQ FROM ODS.WP_FLOW UNION ALL SELECT 'N1A3'FAB ,FLOW_KEY,OPER_NO,OPER_SEQ FROM PWEB.WP_FLOW_A3 ) B ON A.FLOW_ID = B.FLOW_KEY AND A.FAB = B.FAB ) ) ,STACK_FLOW_INFO_PIXEL AS( SELECT PRODG1,ACT_PRODSPEC_ID,PRODSPEC_ID,OPER_NO,ROW_NUMBER()OVER(PARTITION BY ACT_PRODSPEC_ID,FAB ORDER BY FLAG,OPER_SEQ)OPER_SEQ,FAB FROM( SELECT A.PRODG1,A.PRODSPEC_ID ACT_PRODSPEC_ID,A.PRODSPEC_ID,B.OPER_NO ,B.OPER_SEQ,1 FLAG,A.FAB FROM( SELECT DISTINCT FLOW_ID,PRODSPEC_ID,PRODG1,FAB FROM BASE_INFO WHERE (TECH = 'C55STACK' AND PRODG1 LIKE 'C55____M') )A LEFT JOIN ( SELECT 'N1A1'FAB ,FLOW_KEY,OPER_NO,OPER_SEQ FROM ODS.WP_FLOW UNION ALL SELECT 'N1A3'FAB ,FLOW_KEY,OPER_NO,OPER_SEQ FROM PWEB.WP_FLOW_A3 ) B ON A.FLOW_ID = B.FLOW_KEY AND A.FAB = B.FAB UNION ALL SELECT G.PRODG1,G.ACT_PRODSPEC_ID ,G.PRODSPEC_ID,H.OPER_NO,H.OPER_SEQ,2 FLAG,G.FAB FROM( SELECT D.PRODG1,D.ACT_PRODSPEC_ID,D.PRODSPEC_ID,E.FLOW_ID,D.FAB FROM( SELECT A.PRODG1,A.PRODSPEC_ID ACT_PRODSPEC_ID,B.OUTPUT_PRODG,C.CHIPBODY||'.'||SUBSTR(A.PRODSPEC_ID,INSTR(A.PRODSPEC_ID,'.')+1,4) PRODSPEC_ID,A.FAB FROM( SELECT DISTINCT PRODSPEC_ID,PRODG1,FAB FROM BASE_INFO WHERE (TECH = 'C55STACK' AND PRODG1 LIKE 'C55____M') )A LEFT JOIN A1MFG.STACK_LOGIC_RELATED B ON A.PRODG1 = B.PIXEL_PRODG LEFT JOIN PWEB.PRODUCT_INFO C ON B.OUTPUT_PRODG = C.PRODG1 )D LEFT JOIN ( SELECT 'N1A1'FAB, PRODSPEC_ID,PRODG1,FLOW_ID FROM ODS.WP_PRODUCT UNION ALL SELECT 'N1A3'FAB, PRODSPEC_ID,PRODG1,FLOW_ID FROM PWEB.WP_PRODUCT_A3 ) E ON D.PRODSPEC_ID = E.PRODSPEC_ID AND D.FAB = E.FAB )G LEFT JOIN ( SELECT 'N1A1'FAB ,FLOW_KEY,OPER_NO,OPER_SEQ FROM ODS.WP_FLOW UNION ALL SELECT 'N1A3'FAB ,FLOW_KEY,OPER_NO,OPER_SEQ FROM PWEB.WP_FLOW_A3 ) H ON G.FLOW_ID = H.FLOW_KEY AND G.FAB = H.FAB UNION ALL SELECT G.PRODG1,G.ACT_PRODSPEC_ID ,G.PRODSPEC_ID,H.OPER_NO,H.OPER_SEQ,3 FLAG,G.FAB FROM( SELECT D.PRODG1,D.ACT_PRODSPEC_ID,D.PRODSPEC_ID,E.FLOW_ID,D.FAB FROM( SELECT A.PRODG1,A.PRODSPEC_ID ACT_PRODSPEC_ID,B.OUTPUT_PRODG,C.CHIPBODY||'.'||SUBSTR(A.PRODSPEC_ID,INSTR(A.PRODSPEC_ID,'.')+1,4)||'_' PRODSPEC_ID,A.FAB FROM( SELECT DISTINCT PRODSPEC_ID,PRODG1,FAB FROM BASE_INFO WHERE (TECH = 'C55STACK' AND PRODG1 LIKE 'C55____M') )A LEFT JOIN A1MFG.STACK_LOGIC_RELATED B ON A.PRODG1 = B.PIXEL_PRODG LEFT JOIN PWEB.PRODUCT_INFO C ON B.OUTPUT_PRODG = C.PRODG1 )D LEFT JOIN ( SELECT 'N1A1'FAB, PRODSPEC_ID,PRODG1,FLOW_ID FROM ODS.WP_PRODUCT UNION ALL SELECT 'N1A3'FAB, PRODSPEC_ID,PRODG1,FLOW_ID FROM PWEB.WP_PRODUCT_A3 ) E ON D.PRODSPEC_ID = E.PRODSPEC_ID AND D.FAB = E.FAB )G LEFT JOIN ( SELECT 'N1A1'FAB ,FLOW_KEY,OPER_NO,OPER_SEQ FROM ODS.WP_FLOW UNION ALL SELECT 'N1A3'FAB ,FLOW_KEY,OPER_NO,OPER_SEQ FROM PWEB.WP_FLOW_A3 ) H ON G.FLOW_ID = H.FLOW_KEY AND G.FAB = H.FAB ) ) ,STACK_FLOW_INFO_OUTPUT AS( SELECT PRODG1,ACT_PRODSPEC_ID,PRODSPEC_ID,OPER_NO,ROW_NUMBER()OVER(PARTITION BY ACT_PRODSPEC_ID,FAB ORDER BY FLAG,OPER_SEQ)OPER_SEQ,FAB FROM( SELECT A.PRODG1,A.ACT_PRODSPEC_ID,A.PRODSPEC_ID,B.OPER_NO ,B.OPER_SEQ,2 FLAG,A.FAB FROM( SELECT E.FLOW_ID,D.PRODSPEC_ID,D.ACT_PRODSPEC_ID,D.PRODG1,D.FAB FROM( SELECT DISTINCT FLOW_ID,PRODSPEC_ID ACT_PRODSPEC_ID,PRODG1,FAB ,CASE WHEN INSTR(PRODSPEC_ID,'_')>0 THEN REPLACE(PRODSPEC_ID,'_') ELSE PRODSPEC_ID END PRODSPEC_ID FROM BASE_INFO WHERE (TECH = 'C55STACK' AND PRODG1 LIKE 'C55____A') )D LEFT JOIN ( SELECT 'N1A1'FAB, PRODSPEC_ID,PRODG1,FLOW_ID FROM ODS.WP_PRODUCT UNION ALL SELECT 'N1A3'FAB, PRODSPEC_ID,PRODG1,FLOW_ID FROM PWEB.WP_PRODUCT_A3 ) E ON D.PRODSPEC_ID = E.PRODSPEC_ID AND D.FAB = E.FAB )A LEFT JOIN ODS.WP_FLOW B ON A.FLOW_ID = B.FLOW_KEY UNION ALL SELECT G.PRODG1,G.ACT_PRODSPEC_ID ,G.PRODSPEC_ID,H.OPER_NO,H.OPER_SEQ,1 FLAG,G.FAB FROM( SELECT D.PRODG1,D.ACT_PRODSPEC_ID,D.PRODSPEC_ID,E.FLOW_ID,D.FAB FROM( SELECT A.PRODG1,A.ACT_PRODSPEC_ID,B.OUTPUT_PRODG,C.CHIPBODY||'.'||SUBSTR(A.PRODSPEC_ID,INSTR(A.PRODSPEC_ID,'.')+1,4) PRODSPEC_ID,A.FAB FROM( SELECT DISTINCT PRODSPEC_ID ACT_PRODSPEC_ID,PRODG1,FAB ,CASE WHEN INSTR(PRODSPEC_ID,'_')>0 THEN REPLACE(PRODSPEC_ID,'_') ELSE PRODSPEC_ID END PRODSPEC_ID FROM BASE_INFO WHERE (TECH = 'C55STACK' AND PRODG1 LIKE 'C55____A') )A LEFT JOIN A1MFG.STACK_LOGIC_RELATED B ON A.PRODG1 = B.OUTPUT_PRODG LEFT JOIN PWEB.PRODUCT_INFO C ON B.PIXEL_PRODG = C.PRODG1 )D LEFT JOIN ( SELECT 'N1A1'FAB, PRODSPEC_ID,PRODG1,FLOW_ID FROM ODS.WP_PRODUCT UNION ALL SELECT 'N1A3'FAB, PRODSPEC_ID,PRODG1,FLOW_ID FROM PWEB.WP_PRODUCT_A3 ) E ON D.PRODSPEC_ID = E.PRODSPEC_ID AND D.FAB = E.FAB )G LEFT JOIN ( SELECT 'N1A1'FAB ,FLOW_KEY,OPER_NO,OPER_SEQ FROM ODS.WP_FLOW UNION ALL SELECT 'N1A3'FAB ,FLOW_KEY,OPER_NO,OPER_SEQ FROM PWEB.WP_FLOW_A3 ) H ON G.FLOW_ID = H.FLOW_KEY AND G.FAB = H.FAB UNION ALL SELECT G.PRODG1,G.ACT_PRODSPEC_ID ,G.PRODSPEC_ID,H.OPER_NO,H.OPER_SEQ,3 FLAG,G.FAB FROM( SELECT D.PRODG1,D.ACT_PRODSPEC_ID,D.PRODSPEC_ID,E.FLOW_ID,D.FAB FROM( SELECT A.PRODG1,A.ACT_PRODSPEC_ID,A.PRODSPEC_ID||'_' PRODSPEC_ID,A.FAB FROM( SELECT DISTINCT PRODSPEC_ID ACT_PRODSPEC_ID ,CASE WHEN INSTR(PRODSPEC_ID,'_')>0 THEN REPLACE(PRODSPEC_ID,'_') ELSE PRODSPEC_ID END PRODSPEC_ID ,PRODG1,FAB FROM BASE_INFO WHERE (TECH = 'C55STACK' AND PRODG1 LIKE 'C55____A') )A )D LEFT JOIN ( SELECT 'N1A1'FAB, PRODSPEC_ID,PRODG1,FLOW_ID FROM ODS.WP_PRODUCT UNION ALL SELECT 'N1A3'FAB, PRODSPEC_ID,PRODG1,FLOW_ID FROM PWEB.WP_PRODUCT_A3 ) E ON D.PRODSPEC_ID = E.PRODSPEC_ID AND D.FAB = E.FAB )G LEFT JOIN ( SELECT 'N1A1'FAB ,FLOW_KEY,OPER_NO,OPER_SEQ FROM ODS.WP_FLOW UNION ALL SELECT 'N1A3'FAB ,FLOW_KEY,OPER_NO,OPER_SEQ FROM PWEB.WP_FLOW_A3 ) H ON G.FLOW_ID = H.FLOW_KEY AND G.FAB = H.FAB ) ) ,FLOW_INFO_ALL AS( SELECT FAB, PRODG1,ACT_PRODSPEC_ID,PRODSPEC_ID,OPER_NO,OPER_SEQ,CT,TM,TP,TQ,MIN_OPE_SEQ,MAX_OPE_SEQ ,LAYER_STEP_SEQ/LAYER_STEP_COUNT +SUM(CASE WHEN LAYER_STEP_SEQ=1 THEN 1 ELSE 0 END)OVER(PARTITION BY ACT_PRODSPEC_ID,FAB ORDER BY OPER_SEQ)-1 REMAIN_LAYER ,SUM(CASE WHEN LAYER_STEP_SEQ=1 THEN 1 ELSE 0 END)OVER(PARTITION BY ACT_PRODSPEC_ID,FAB )MAX_LAYER_COUNT FROM( SELECT FAB, PRODG1,ACT_PRODSPEC_ID,PRODSPEC_ID,OPER_NO,OPER_SEQ,CT,TM,TP,TQ ,COUNT(1)OVER(PARTITION BY FAB,ACT_PRODSPEC_ID,SUBSTR(OPER_NO,1,2))LAYER_STEP_COUNT ,ROW_NUMBER()OVER(PARTITION BY FAB,ACT_PRODSPEC_ID,SUBSTR(OPER_NO,1,2) ORDER BY OPER_SEQ)LAYER_STEP_SEQ ,MIN(OPER_SEQ)OVER(PARTITION BY ACT_PRODSPEC_ID,FAB)MIN_OPE_SEQ ,MAX(OPER_SEQ)OVER(PARTITION BY ACT_PRODSPEC_ID,FAB)MAX_OPE_SEQ FROM( SELECT FAB, PRODG1,ACT_PRODSPEC_ID,PRODSPEC_ID,OPER_NO,OPER_SEQ,CT,TM,TP ,CASE WHEN TQ IS NOT NULL THEN TQ WHEN CT - TM - TP < 0 THEN 0 ELSE CT - TM - TP END TQ FROM( SELECT A.*,B.TQ ,CASE WHEN B.CT IS NOT NULL THEN B.CT WHEN NVL(E.SAMPLING_RATE,1) = 0 THEN 0 ELSE D.INLINE_CT END CT ,CASE WHEN B.TM IS NOT NULL THEN B.TM WHEN NVL(E.SAMPLING_RATE,1) = 0 THEN 0 WHEN SUBSTR(A.OPER_NO,5,1) = 'Q' OR A.OPER_NO LIKE '%SXW%' OR A.OPER_NO LIKE '%SXN%' THEN D.TC+0.1 ELSE D.TC+0.2 END TM ,CASE WHEN B.TP IS NOT NULL THEN B.TP WHEN NVL(E.SAMPLING_RATE,1) = 0 THEN 0 ELSE 0.05 END TP FROM( SELECT FAB,PRODG1,ACT_PRODSPEC_ID,PRODSPEC_ID,OPER_NO,OPER_SEQ FROM FLOW_BASE_INFO UNION ALL SELECT FAB,PRODG1,ACT_PRODSPEC_ID,PRODSPEC_ID,OPER_NO,OPER_SEQ FROM STACK_FLOW_INFO_PIXEL UNION ALL SELECT FAB,PRODG1,ACT_PRODSPEC_ID,PRODSPEC_ID,OPER_NO,OPER_SEQ FROM STACK_FLOW_INFO_OUTPUT )A LEFT JOIN A1MFG.PRODUCT_FLOW_INFO B ON A.PRODG1 = B.PRODG1 AND A.OPER_NO = B.OPER_NO LEFT JOIN PWEB.OPE_NO_INLINE_FLOW_PSTD D ON A.PRODSPEC_ID = D.PRODSPEC_ID AND A.OPER_NO = D.OPE_NO LEFT JOIN PWEB.SAMPLING_RATE E ON A.PRODSPEC_ID = E.PRODSPEC_ID AND A.OPER_NO = E.OPE_NO )C ))) ,REQUEST_BASE_INFO AS( SELECT A.FAB,A.FUNCTION_NAME, A.LOT_ID,A.PRODSPEC_ID,A.LAST_MAIN_OPENO,A.LOT_PROC_STATE,A.LAST_CLAIM_TIME ,NVL(B.OPER_SEQ,E.MIN_OPE_SEQ) CUR_SEQ,A.TARGET_OPE ,NVL(C.OPER_SEQ,E.MAX_OPE_SEQ) TARGET_SEQ,A.REQUEST_DAY ,NVL(C.OPER_SEQ,E.MAX_OPE_SEQ)-NVL(B.OPER_SEQ,E.MIN_OPE_SEQ) REMAIN_STEP ,TO_DATE(REQUEST_DAY,'YYYYMMDD') - TRUNC(SYSDATE) +1 REMAIN_DAY ,ROUND(NVL(C.REMAIN_LAYER,E.MAX_LAYER_COUNT) - B.REMAIN_LAYER,1) REMAIN_LAYER FROM BASE_INFO A LEFT JOIN FLOW_INFO_ALL B ON A.PRODSPEC_ID = B.ACT_PRODSPEC_ID AND A.LAST_MAIN_OPENO = B.OPER_NO AND A.FAB = B.FAB LEFT JOIN FLOW_INFO_ALL C ON A.PRODSPEC_ID = C.ACT_PRODSPEC_ID AND A.TARGET_OPE = C.OPER_NO AND A.FAB = C.FAB LEFT JOIN ( SELECT DISTINCT ACT_PRODSPEC_ID,FAB,MIN_OPE_SEQ,MAX_OPE_SEQ,MAX_LAYER_COUNT FROM FLOW_INFO_ALL )E ON A.PRODSPEC_ID = E.ACT_PRODSPEC_ID AND A.FAB = E.FAB ) ,TF_INFO AS( SELECT FAB, PRODSPEC_ID,LOT_ID ,CASE WHEN REMAIN_DAY - TM_SUM - TP_SUM<0 OR TQ_SUM <=0 THEN 0 WHEN REMAIN_DAY - TM_SUM - TP_SUM > TQ_SUM THEN 1 ELSE (REMAIN_DAY - TM_SUM - TP_SUM) / TQ_SUM END TF_ FROM( SELECT FAB,PRODSPEC_ID,LOT_ID,SUM(CT)CT_SUM,SUM(TM)TM_SUM,SUM(TP)TP_SUM,SUM(TQ)TQ_SUM,MAX(REMAIN_DAY)*24 REMAIN_DAY FROM( SELECT A.*,B.OPER_NO,B.CT,B.TM,B.TP,B.TQ FROM REQUEST_BASE_INFO A LEFT JOIN FLOW_INFO_ALL B ON A.PRODSPEC_ID = B.ACT_PRODSPEC_ID AND A.FAB = B.FAB WHERE B.OPER_SEQ BETWEEN A.CUR_SEQ AND NVL(A.TARGET_SEQ,9999) )GROUP BY FAB,PRODSPEC_ID,LOT_ID )) SELECT FUNCTION_NAME,LOT_ID,PRODSPEC_ID,LAST_MAIN_OPENO,CUR_SEQ,OPER_NO,OPER_SEQ,TM,STD_CT ,NVL(LAG(CT_FORECAST)OVER(PARTITION BY LOT_ID,PRODSPEC_ID,FUNCTION_NAME ORDER BY OPER_SEQ),0) CT_FORECAST ,TF_ FLOW_TF,REMAIN_LAYER LAYER_COUNT,SYSDATE UPDATE_TIME FROM( SELECT A.FUNCTION_NAME, LOT_ID,PRODSPEC_ID,LAST_MAIN_OPENO,CUR_SEQ,OPER_NO,OPER_SEQ,TM ,SUM(CT)OVER(PARTITION BY LOT_ID,FUNCTION_NAME ORDER BY OPER_SEQ) CT_FORECAST ,STD_CT,TF_,REMAIN_LAYER FROM( SELECT A.*,B.OPER_NO,C.TF_,B.TM,B.TP,B.TQ*C.TF_ TQ,B.OPER_SEQ,B.TM+B.TP+B.TQ*C.TF_ STD_CT --如果是Procession，当站数据需要减去已经过去的 TM,TQ,TP ,CASE WHEN A.LOT_PROC_STATE = 'Processing' AND A.CUR_SEQ = B.OPER_SEQ THEN GREATEST(B.TM-(SYSDATE-LAST_CLAIM_TIME)*24,0.2) WHEN A.LOT_PROC_STATE <> 'Processing' AND A.CUR_SEQ = B.OPER_SEQ AND B.TQ*C.TF_-(SYSDATE-LAST_CLAIM_TIME)*24>0.2 THEN B.TQ*C.TF_-(SYSDATE-LAST_CLAIM_TIME)*24 + TM+TP WHEN A.LOT_PROC_STATE <> 'Processing' AND A.CUR_SEQ = B.OPER_SEQ THEN 0.2 + TM+TP ELSE B.TQ*C.TF_+B.TM+B.TP END CT FROM REQUEST_BASE_INFO A LEFT JOIN FLOW_INFO_ALL B ON A.PRODSPEC_ID = B.ACT_PRODSPEC_ID AND A.FAB = B.FAB LEFT JOIN TF_INFO C ON A.LOT_ID = C.LOT_ID AND A.PRODSPEC_ID = C.PRODSPEC_ID AND A.FAB = C.FAB WHERE B.OPER_SEQ BETWEEN A.CUR_SEQ AND NVL(A.TARGET_SEQ,9999) )A)

