UPDATE A1MFG.PULLIN_LOT_UPLOAD
SET TOP_FLAG = CASE WHEN TOP_FLAG = 'Y' THEN 'N' ELSE 'Y' END,
UPDATE_TIME = SYSDATE,UPDATE_USER = #{updateUser}
WHERE INSTR(','|| #{lotIdList}||',',','||LOT_ID||',')>0
AND FUNCTION_NAME = #{functionName,jdbcType=VARCHAR}

UPDATE PWEB.COMMENT_SUMMARY
SET KEY5 = #{active},KEY4 = #{rank},UPDATE_TIME = SYSDATE,UPDATE_USER = #{updateUser}
,KEY2 = #{label}
WHERE FUNCTION_NAME =  'PULLINWEB_TABNAME'
AND KEY1 = #{tabName,jdbcType=VARCHAR}
AND KEY3 = #{fab,jdbcType=VARCHAR}
